#include "Library.h"
#include <iostream>
#include <limits>
int readInt(const std::string& p){int v;for(;;){std::cout<<p;if(std::cin>>v){std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');return v;}std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');std::cout<<"Please enter a valid number.\n";}}
void seed(Library& l){l.addBook(Book(101,"C++ Primer","Stanley Lippman"));l.addBook(Book(102,"Clean Code","Robert C. Martin"));l.addBook(Book(103,"The Pragmatic Programmer","David Thomas"));l.addMember(Member(1,"Aarav"));l.addMember(Member(2,"Priya"));}
int main(){Library l;const std::string f="library_records.txt";if(!l.load(f)){seed(l);l.save(f);}for(;;){std::cout<<"\n=== Library Manager ===\n1. List books\n2. Search books\n3. Issue book\n4. Return book\n5. Show report\n6. Save & exit\n";int c=readInt("Choose: ");if(c==1){for(const auto& b:l.books())std::cout<<b.getId()<<" | "<<b.getTitle()<<" | "<<b.getAuthor()<<" | "<<(b.isAvailable()?"Available":"Issued")<<'\n';}else if(c==2){std::string q;std::cout<<"Keyword: ";std::getline(std::cin,q);auto r=l.searchBooks(q);std::cout<<r.size()<<" result(s)\n";for(auto* b:r)std::cout<<b->getId()<<" | "<<b->getTitle()<<" | "<<b->getAuthor()<<'\n';}else if(c==3){int b=readInt("Book ID: "),m=readInt("Member ID: ");std::cout<<(l.issueBook(b,m,"2026-10-06")?"Book issued successfully.\n":"Issue failed.\n");}else if(c==4){int b=readInt("Book ID: ");std::cout<<(l.returnBook(b)?"Book returned successfully.\n":"Return failed.\n");}else if(c==5){auto r=l.getReport();std::cout<<"\n--- Library Report ---\nTotal books: "<<r.totalBooks<<"\nAvailable: "<<r.availableBooks<<"\nIssued: "<<r.issuedBooks<<"\nMembers: "<<r.totalMembers<<"\nActive loans: "<<r.activeLoans<<"\n";}else if(c==6){if(!l.save(f))return 1;std::cout<<"Saved. Goodbye!\n";return 0;}else std::cout<<"Invalid choice.\n";}}
